//! The tree build is fully deterministic. Every node gets an id (leaves use\n//! their byte value 0..=255, internal nodes use 256 + merge step) and the\n//! priority queue orders nodes by `(weight, id)`. Because that key is unique,\n//! the tree only depends on the frequency table, so the decompressor can\n//! rebuild the exact same tree from the header alone.\n\nuse rayon::prelude::*;\nuse std::cmp::{Ordering, Reverse};\nuse std::collections::BinaryHeap;\n\npub type Freq = [u64; 256];\n\npub struct Node {\n    pub weight: u64,\n    pub id: u32,\n    pub symbol: Option<u8>,\n    pub left: Option<Box<Node>>,\n    pub right: Option<Box<Node>>,\n}\n\nimpl Node {\n    fn is_leaf(&self) -> bool {\n        self.left.is_none() && self.right.is_none()\n    }\n}\n\nimpl PartialEq for Node {\n    fn eq(&self, other: &Self) -> bool {\n        self.weight == other.weight && self.id == other.id\n    }\n}\nimpl Eq for Node {}\nimpl PartialOrd for Node {\n    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {\n        Some(self.cmp(other))\n    }\n}\n"},"frequencies":[{"sym":10,"count":40},{"sym":32,"count":200},{"sym":33,"count":8},{"sym":38,"count":9},{"sym":40,"count":9},{"sym":41,"count":9},{"sym":42,"count":1},{"sym":43,"count":1},{"sym":44,"count":15},{"sym":45,"count":3},{"sym":46,"count":15},{"sym":47,"count":16},{"sym":48,"count":1},{"sym":50,"count":4},{"sym":51,"count":1},{"sym":52,"count":2},{"sym":53,"count":4},{"sym":54,"count":4},{"sym":56,"count":1},{"sym":58,"count":20},{"sym":59,"count":5},{"sym":60,"count":6},{"sym":61,"count":6},{"sym":62,"count":9},{"sym":66,"count":4},{"sym":67,"count":1},{"sym":69,"count":3},{"sym":70,"count":1},{"sym":72,"count":2},{"sym":78,"count":7},{"sym":79,"count":7},{"sym":80,"count":2},{"sym":82,"count":1},{"sym":83,"count":3},{"sym":84,"count":1},{"sym":91,"count":1},{"sym":93,"count":1},{"sym":95,"count":4},{"sym":96,"count":2},{"sym":97,"count":27},{"sym":98,"count":18},{"sym":99,"count":19},{"sym":100,"count":35},{"sym":